INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT159-S1-Q11$batch11$, 159, 1, 11, $batch11$Weaken$batch11$, $batch11$Ross: Many governments have attempted to regulate strictly or even outlaw theater because of its subversive power. Such strategies have rarely succeeded, probably because people strongly desire theater for entertainment and dramatists always find subtle ways to criticize authorities who treat them harshly. Thus, since dramatists will not criticize governments of which they are honored employees, an effective strategy for controlling theater and satisfying the public is to make dramatists and performers honored employees of the government.$batch11$, $batch11$Which one of the following, if true, would most weaken Ross’s argument?$batch11$, $batch11$E$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q11$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Few governments are willing to shoulder the expense of employing dramatists and performers.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Even when completely unregulated, theater rarely leads to the overthrow of a government.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Some dramatists criticize their governments even though those governments do not treat them harshly.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Most theatrical productions neither criticize government nor support it.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$The public generally dislikes plays written or performed by government employees.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Making dramatists and performers honored government employees is an effective way to control theater and satisfy the public.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Banning theater fails because people want theater for entertainment and dramatists find ways to criticize harsh authorities. Dramatists won't criticize governments that honor and employ them.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The plan has two goals: control theater and satisfy the public. The argument shows how employing dramatists stops criticism. It assumes the public will still enjoy the plays. If people dislike plays by government employees, the plan fails the second goal.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Show the public won't be satisfied by government-employed dramatists.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Few governments being willing doesn't show the plan wouldn't work.$batch11$), ($batch11$B$batch11$, $batch11$Theater rarely toppling governments doesn't affect whether this plan controls it.$batch11$), ($batch11$C$batch11$, $batch11$Criticism of non-harsh governments isn't the same as criticism by honored employees. Ross's claim is about the latter.$batch11$), ($batch11$D$batch11$, $batch11$Most plays ignoring government doesn't affect whether the plan works.$batch11$), ($batch11$E$batch11$, $batch11$If the public dislikes plays by government employees, the plan fails to satisfy the public.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT159-S1-Q11$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
